59. #[verus_spec(result =>
60.     requires
61.         phys_view().initialized,
62.         phys_view().inv(),
63.     ensures
64.         phys_view().inv(),
65.         phys_view().initialized,
66.         match result {
67.             Ok(_) => phys_view().frames.all_reserved(
68.                 phys_regions_frame_set(&physical_memory_regions)),
69.             Err(_) => true,
70.         },
71. )]
72. fn book_physical_memory_regions(
73.     physical_memory_regions: LinkedList<TruncatedMemoryRegion<PhysicalAddress>>,
74. ) -> Result<(), Error> {
75.     info!("booking physical memory regions ...");
76. 
77.     // Book physical memory that is not usable.
78.     for region in physical_memory_regions.iter() {
79.         info!("booking: {:?}", region);
80.         frame::alloc_range(region)?;
81.     }
82. 
83.     Ok(())
84. }
85. 
86. #[verus_spec(result =>
87.     requires
88.         phys_view().initialized,
89.         phys_view().inv(),
90.     ensures
91.         phys_view().inv(),
92.         phys_view().initialized,
93.         match result {
94.             Ok(_) => forall|a: int|
95.                 #[trigger] mmio_regions_frame_set(mmio_regions).contains(a)
96.                     && phys_view().frames.covers(a)
97.                     ==> phys_view().frames.reserved(a),
98.             Err(_) => true,
99.         },
100. )]
101. fn book_mmio_regions(
102.     mmio_regions: &LinkedList<TruncatedMemoryRegion<VirtualAddress>>,
103. ) -> Result<(), Error> {
104.     info!("booking memory-mapped i/o regions ...");
105. 
106.     // Book memory-mapped I/O regions.
107.     for region in mmio_regions.iter() {
108.         info!("booking: {:?}", region);
109.         let mut start: usize = region.start().into_raw_value();
110.         let end: usize = start + (region.size() - 1);
111.         while start < end {
112.             let mmio_addr: usize = crate::hal::platform::gva_to_gpa(start);
113.             let phys_addr: PageAligned<PhysicalAddress> = PageAligned::from_address(unsafe {
114.                 // MMIO GPAs may legitimately lie outside tracked RAM, so they must not go through
115.                 // the regular physical-address validator here.
116.                 PhysicalAddress::from_mmio_address(VirtualAddress::from_raw_value(mmio_addr))?
117.             })?;
118. 
119.             // Only book frames that the frame allocator actually tracks.
120.             // MMIO regions above RAM (e.g. the LAPIC at 0xFEE0_0000) are not
121.             // covered by the bitmap and must be skipped.
122.             if frame::is_covered(phys_addr) {
123.                 frame::book(phys_addr)?;
124.             }
125.             start += mem::FRAME_SIZE;
126.         }
127.     }
128. 
129.     Ok(())
130. }
