132. ///
133. /// # Description
134. ///
135. /// Initializes the physical memory manager.
136. ///
137. /// # Parameters
138. ///
139. /// - `physical_memory_regions`: Physical memory regions to book.
140. /// - `mmio_regions`: Memory-mapped I/O regions to book.
141. /// - `physical_memory_layout`: Physical memory layout bitmap.
142. ///
143. /// # Returns
144. ///
145. /// Upon success, `Ok(())` is returned. Upon failure, an error is returned instead.
146. ///
147. #[verus_spec(result =>
148.     requires
149.         phys_view().inv(),
150.     ensures
151.         phys_view().inv(),
152.         match result {
153.             Ok(_) => {
154.                 &&& phys_view().live()
155.                 &&& phys_view().frames.all_reserved(
156.                     phys_regions_frame_set(&physical_memory_regions))
157.                 &&& forall|a: int|
158.                     #[trigger] mmio_regions_frame_set(mmio_regions).contains(a)
159.                         && phys_view().frames.covers(a)
160.                         ==> phys_view().frames.reserved(a)
161.             },
162.             Err(_) => true,
163.         },
164. )]
165. pub fn init(
166.     physical_memory_regions: LinkedList<TruncatedMemoryRegion<PhysicalAddress>>,
167.     mmio_regions: &LinkedList<TruncatedMemoryRegion<VirtualAddress>>,
168.     physical_memory_layout: Bitmap,
169. ) -> Result<(), Error> {
170.     // Initialize frame allocator singleton.
171.     info!("initializing the frame allocator ...");
172.     // Safety: called exactly once during single-threaded boot.
173.     unsafe { frame::init(physical_memory_layout)? };
174.     proof!{
175.         lemma_frame_initialized();
176.     }
177.     book_physical_memory_regions(physical_memory_regions)?;
178. 
179.     book_mmio_regions(mmio_regions)?;
180. 
181.     // Initialize user page pool.
182.     info!("initializing the user page pool ...");
183.     let upool: Upool = Upool::new();
184. 
185.     // Initialize physical memory manager singleton.
186.     info!("initializing the physical memory manager ...");
187.     PhysMemoryManager::init(upool)?;
188.     proof!{
189.         lemma_manager_ready();
190.     }
191. 
192.     Ok(())
193. }
